import Foundation
import SwiftUI
#if canImport(AppKit)
import AppKit
#else
import UIKit
#endif

/// **The real logo of each cloud provider that makes a server from this Mac** (the owner's yes of 9 November 2026 to the
/// VPS page that showed each provider's logo with one short line under its name). Each is the provider's mark from
/// Simple Icons 16.36.0 (simpleicons.org), in the provider's own colour, at 128 pixels as the AI providers' logos are, on
/// a clear ground: the page puts it on a white tile, and Hetzner's red square is the whole tile. The bytes stand here,
/// as `ProviderLogo`'s do, so the apps bundle no image file and read no network. The logos are their owners' marks:
/// Founderizer shows them only to name the provider.
public enum CloudLogo {
    /// The logo of a cloud provider by the app's name for it (`CloudProvider.rawValue`), nil for one that has none here.
    public static func image(_ provider: String) -> Image? {
        switch provider {
        case "hetzner": hetzner
        case "digitalocean": digitalOcean
        case "vultr": vultr
        case "akamai": akamai
        default: nil
        }
    }

    /// Whether the logo is the whole tile, as Hetzner's red square is, rather than a mark in the middle of a white one.
    public static func fillsTile(_ provider: String) -> Bool { provider == "hetzner" }

    private static let hetzner = decode(hetznerBytes)
    private static let digitalOcean = decode(digitalOceanBytes)
    private static let vultr = decode(vultrBytes)
    private static let akamai = decode(akamaiBytes)

    private static func decode(_ bytes: String) -> Image? {
        guard let data = Data(base64Encoded: bytes) else { return nil }
        #if canImport(AppKit)
        return NSImage(data: data).map(Image.init(nsImage:))
        #else
        return UIImage(data: data).map(Image.init(uiImage:))
        #endif
    }

    // Simple Icons 16.36.0, icons/hetzner.svg, #D50C2D
    static let hetznerBytes = ""
    // Simple Icons 16.36.0, icons/digitalocean.svg, #0080FF
    static let digitalOceanBytes = ""
    // Simple Icons 16.36.0, icons/vultr.svg, #007BFC
    static let vultrBytes = ""
    // Simple Icons 16.36.0, icons/akamai.svg, #0096D6
    static let akamaiBytes = ""
}
